source.chatCss:
:scope#bg1, :scope#bg_custom {
background-color: var(--cqs-canvas);
background-image:
linear-gradient(color-mix(in srgb, var(--cqs-border) 55%, transparent) 1px, transparent 1px),
linear-gradient(90deg, color-mix(in srgb, var(--cqs-border) 55%, transparent) 1px, transparent 1px),
radial-gradient(70% 50% at 50% 0%, color-mix(in srgb, var(--cqs-headerA) 90%, transparent), transparent 75%);
background-size: 28px 28px, 28px 28px, auto;
}
:scope #chat {
background-color: color-mix(in srgb, var(--cqs-surface) 92%, transparent);
background-image: linear-gradient(90deg, transparent 46px, color-mix(in srgb, var(--cqs-accent) 22%, transparent) 46px 47px, transparent 47px);
border-inline: 1px solid var(--cqs-border);
box-shadow: 0 0 0 6px color-mix(in srgb, var(--cqs-surface) 40%, transparent);
}
:scope[data-cqs-mode="flat"] #chat .mes { border-bottom: 1px dashed var(--cqs-border); }
:scope[data-cqs-mode="flat"] #chat .mes[is_user="true"] {
background: color-mix(in srgb, var(--cqs-user) 75%, transparent);
border-radius: 14px;
border-bottom-color: transparent;
margin: 6px 10px;
}
:scope #chat .mes:not([is_user="true"]) .ch_name .name_text::before { content: "\273F  "; color: color-mix(in srgb, var(--cqs-accent) 60%, var(--cqs-surface)); }
:scope #chat .mes .ch_name .name_text { font-weight: 800; }
:scope #chat .mes .avatar img { border-radius: 14px; border: 2px solid var(--cqs-surface); box-shadow: 0 0 0 1px var(--cqs-border); }
:scope #chat .mes_text q { background: linear-gradient(transparent 58%, color-mix(in srgb, var(--cqs-accentSoft) 95%, transparent) 58%); }
:scope #chat .mes_text blockquote { border-left: 3px dashed var(--cqs-accent); border-radius: 0; }
:scope #send_form {
border: 1px solid var(--cqs-border);
border-radius: 14px;
background: var(--cqs-surface);
box-shadow: inset 0 2px 0 color-mix(in srgb, var(--cqs-accentSoft) 80%, transparent), 0 8px 22px -18px var(--cqs-accent);
}
:scope #send_form:focus-within { border-color: color-mix(in srgb, var(--cqs-accent) 50%, var(--cqs-border)); }
:scope#options .options-content { border-radius: 14px; border: 1px dashed var(--cqs-border); }

source.menuCss:
:scope#top-bar {
background: linear-gradient(180deg, color-mix(in srgb, var(--cqs-headerA) 60%, var(--cqs-surface)), var(--cqs-surface));
border-bottom: 1px solid var(--cqs-border);
box-shadow: 0 6px 18px -16px var(--cqs-accent);
}
:scope#top-bar::after {
content: ""; position: absolute; left: 8px; right: 8px; bottom: 4px; height: 0; pointer-events: none;
border-bottom: 1.5px dashed color-mix(in srgb, var(--cqs-accent) 30%, transparent);
}
:scope .drawer-icon { color: color-mix(in srgb, var(--cqs-accent) 45%, var(--cqs-muted)); }
:scope .drawer-icon:hover, :scope .drawer-icon.openIcon { color: var(--cqs-accent); }
:scope .drawer-content { border: 1px solid var(--cqs-border); border-radius: 16px; box-shadow: 0 18px 36px -28px var(--cqs-accent); }
